// Per-node stake contract (BLOCKCHAIN_ECONOMICS §8). Non-custodial: no human key
// controls the funds — deposit, unbond cooldown, slashing and keeper withdrawal
// are all governed by contract code. The vault is ALSO the master of this node's
// transfer-locked stake-receipt jetton (§8.5): it mints 1:1 on deposit and burns
// on withdrawal/slash.
//
// This contract is only ever touched by PAID work. Free jobs (§8.2) bypass it
// entirely via the off-chain NoopSettlement path.

import "common"
import "stake_types"

contract StakeVault {
    storage: VaultStorage
    incomingMessages: AllowedMessageToVault
}

type AllowedMessageToVault =
    | StakeDeposit
    | StakeRequestUnbond
    | StakeWithdraw
    | StakeKeeperWithdraw
    | StakeSlash
    | ReceiptTopUp

fun onBouncedMessage(_in: InMessageBounced) {}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToVault.fromSlice(in.body);

    match (msg) {
        // Deposit: bond `amount` (held non-custodially in this contract) and mint
        // an equal amount of the transfer-locked stake-receipt jetton to the owner.
        StakeDeposit => {
            var storage = lazy VaultStorage.load();
            assert (in.senderAddress == storage.owner) throw ERROR_NOT_OWNER;
            assert (in.valueCoins >= msg.amount + MIN_TONS_FOR_STORAGE) throw ERROR_NOT_ENOUGH_GAS;

            storage.staked += msg.amount;
            storage.totalSupply += msg.amount;
            storage.save();

            val cfg = storage.config.load();
            mintReceipt(
                storage.owner,
                contract.getAddress(),
                cfg.receiptWalletCode,
                msg.amount,
                msg.queryId,
            );
        }

        // Begin unbonding: move `amount` from the bonded bucket into the cooldown
        // bucket. The cooldown stake stays SLASHABLE (§8.4) and the receipt stays
        // locked until withdrawal completes.
        StakeRequestUnbond => {
            var storage = lazy VaultStorage.load();
            assert (in.senderAddress == storage.owner) throw ERROR_NOT_OWNER;
            assert (storage.unbondingAt == 0) throw ERROR_UNBOND_IN_PROGRESS;
            assert (msg.amount > 0 && msg.amount <= storage.staked) throw ERROR_NOTHING_TO_UNBOND;

            storage.staked -= msg.amount;
            storage.unbondingAmount = msg.amount;
            storage.unbondingAt = blockchain.now() as uint32;
            storage.save();
        }

        // Owner withdrawal after the cooldown elapses: release the cooled stake and
        // burn the matching receipts.
        StakeWithdraw => {
            var storage = lazy VaultStorage.load();
            assert (in.senderAddress == storage.owner) throw ERROR_NOT_OWNER;
            assert (storage.unbondingAmount > 0) throw ERROR_NO_UNBONDING;
            val cfg = storage.config.load();
            val readyAt = storage.unbondingAt + cfg.unbondingPeriod;
            assert (blockchain.now() >= readyAt) throw ERROR_COOLDOWN_NOT_ELAPSED;

            val amount = storage.unbondingAmount;
            storage.unbondingAmount = 0;
            storage.unbondingAt = 0;
            storage.totalSupply -= amount;
            storage.save();

            burnReceipt(
                storage.owner,
                contract.getAddress(),
                cfg.receiptWalletCode,
                amount,
                msg.queryId,
            );
            payout(storage.owner, amount);
        }

        // Keeper liveness (TON idiom, §8.4): once cooldown + grace elapses, ANYONE
        // can finalize an unresponsive owner's withdrawal and earn a small bounty.
        StakeKeeperWithdraw => {
            var storage = lazy VaultStorage.load();
            assert (storage.unbondingAmount > 0) throw ERROR_NO_UNBONDING;
            val cfg = storage.config.load();
            val keeperAt = storage.unbondingAt + cfg.unbondingPeriod + cfg.keeperGrace;
            assert (blockchain.now() >= keeperAt) throw ERROR_KEEPER_TOO_EARLY;

            val amount = storage.unbondingAmount;
            storage.unbondingAmount = 0;
            storage.unbondingAt = 0;
            storage.totalSupply -= amount;
            storage.save();

            val bounty = mulDivFloor(amount, cfg.keeperBountyBps, BPS_DENOM);
            burnReceipt(
                storage.owner,
                contract.getAddress(),
                cfg.receiptWalletCode,
                amount,
                msg.queryId,
            );
            payout(storage.owner, amount - bounty);
            if (bounty > 0) {
                payout(in.senderAddress, bounty);
            }
        }

        // Graduated slashing (§8.3) by the authorized slasher (dispute contract).
        // Takes from the bonded bucket first, then the still-slashable cooldown
        // bucket, splits the slashed funds per config, and burns the receipts.
        StakeSlash => {
            var storage = lazy VaultStorage.load();
            val cfg = storage.config.load();
            assert (in.senderAddress == cfg.slasher) throw ERROR_NOT_SLASHER;
            val slashable = storage.staked + storage.unbondingAmount;
            assert (msg.amount > 0 && msg.amount <= slashable) throw ERROR_SLASH_EXCEEDS_STAKE;

            val fromStaked = min(msg.amount, storage.staked);
            storage.staked -= fromStaked;
            storage.unbondingAmount -= (msg.amount - fromStaked);
            storage.totalSupply -= msg.amount;
            storage.save();

            burnReceipt(
                storage.owner,
                contract.getAddress(),
                cfg.receiptWalletCode,
                msg.amount,
                msg.queryId,
            );
            applySlashSplit(cfg.slash.load(), msg.amount, msg.challenger);
        }

        ReceiptTopUp => {
            // accept TON top-ups for storage rent
        }

        else => {
            assert (in.body.isEmpty()) throw ERROR_INVALID_OP;
        }
    }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

fun mintReceipt(owner: address, master: address, walletCode: cell, amount: coins, queryId: int) {
    val dest = calcDeployedReceiptWallet(owner, master, walletCode);
    val m = createMessage({
        bounce: BounceMode.NoBounce,
        dest: dest,
        value: MIN_TONS_FOR_STORAGE,
        body: ReceiptMint {
            queryId: queryId,
            amount: amount,
        },
    });
    m.send(SEND_MODE_PAY_FEES_SEPARATELY);
}

fun burnReceipt(owner: address, master: address, walletCode: cell, amount: coins, queryId: int) {
    val dest = calcReceiptWalletAddress(owner, master, walletCode);
    val m = createMessage({
        bounce: BounceMode.NoBounce,
        dest: dest,
        value: ton("0.02"),
        body: ReceiptBurn {
            queryId: queryId,
            amount: amount,
        },
    });
    m.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_IGNORE_ERRORS);
}

fun payout(to: address, amount: coins) {
    val m = createMessage({
        bounce: BounceMode.NoBounce,
        dest: to,
        value: amount,
    });
    m.send(SEND_MODE_PAY_FEES_SEPARATELY | SEND_MODE_IGNORE_ERRORS);
}

// Split slashed funds: challenger bounty / redundancy-reward pool / burn /
// treasury (§8.3). The burn share is simply left locked in this contract (no key
// can release it), which removes it from circulation.
fun applySlashSplit(sc: SlashConfig, amount: coins, challenger: address) {
    val sum = sc.splitChallengerBps + sc.splitRedundancyBps + sc.splitBurnBps + sc.splitTreasuryBps;
    assert (sum == BPS_DENOM) throw ERROR_INVALID_SPLIT;

    val challengerAmt = mulDivFloor(amount, sc.splitChallengerBps, BPS_DENOM);
    val redundancyAmt = mulDivFloor(amount, sc.splitRedundancyBps, BPS_DENOM);
    val treasuryAmt = mulDivFloor(amount, sc.splitTreasuryBps, BPS_DENOM);
    // burn share = remainder, left locked in the vault forever.

    if (challengerAmt > 0) {
        payout(challenger, challengerAmt);
    }
    if (redundancyAmt > 0) {
        payout(sc.redundancyPool, redundancyAmt);
    }
    if (treasuryAmt > 0) {
        payout(sc.treasury, treasuryAmt);
    }
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

get fun get_vault_state(): VaultState {
    val storage = lazy VaultStorage.load();
    val cfg = storage.config.load();
    val eligible = storage.staked >= cfg.minStake && storage.unbondingAt == 0;
    return {
        staked: storage.staked,
        unbondingAmount: storage.unbondingAmount,
        unbondingAt: storage.unbondingAt,
        totalSupply: storage.totalSupply,
        eligible: eligible,
    };
}

get fun get_owner(): address {
    val storage = lazy VaultStorage.load();
    return storage.owner;
}

get fun get_binding_hash(): int {
    val storage = lazy VaultStorage.load();
    return storage.bindingHash;
}

get fun get_receipt_wallet_address(owner: address): address {
    val storage = lazy VaultStorage.load();
    val cfg = storage.config.load();
    return calcReceiptWalletAddress(owner, contract.getAddress(), cfg.receiptWalletCode);
}

get fun is_eligible(): bool {
    val storage = lazy VaultStorage.load();
    val cfg = storage.config.load();
    return storage.staked >= cfg.minStake && storage.unbondingAt == 0;
}

// Shared error codes, opcodes and constants for the duckdb-p2p settlement layer.
//
// These contracts implement the *paid* path of the economic layer described in
// `docs/BLOCKCHAIN_ECONOMICS.md`. Free jobs never touch any of this code — the
// requester runs them through the off-chain coordinator with the `NoopSettlement`
// path and there is zero on-chain interaction (see §8.2 "Free vs paid path").
//
// Design constraints honoured here (BLOCKCHAIN_ECONOMICS §1, §8):
//   * sharded per-node state (no global contract): one StakeVault per node,
//     one JobEscrow per job — never a single hot contract.
//   * non-custodial: release is governed entirely by contract code (quorum
//     result-hash, challenge window, unbonding cooldown), never a platform key.
//   * defensive TON style: explicit gas floors, bounce-safe, carry-value.
// ---------------------------------------------------------------------------
// Error codes (numeric, cheap to assert against in tests)
// ---------------------------------------------------------------------------

const ERROR_NOT_OWNER = 132 // sender is not the contract owner
const ERROR_NOT_FROM_MASTER = 133 // sender is not the jetton master (vault)
const ERROR_NOT_VALID_WALLET = 134 // sender is not a legitimate sibling receipt wallet
const ERROR_UNAUTHORIZED_BURN = 135 // burn notification not from the owner's wallet
const ERROR_BALANCE_NEGATIVE = 136 // resulting balance would be negative
const ERROR_NOT_ENOUGH_GAS = 137 // attached value too small to cover the operation
const ERROR_RECEIPT_LOCKED = 138 // stake-receipt jetton is non-transferable (anti-exit)
const ERROR_WRONG_WORKCHAIN = 333 // address is not in the basechain
const ERROR_INVALID_OP = 0xffff // unknown opcode

// Stake vault
const ERROR_NOT_SLASHER = 200 // sender is not the authorized slasher (dispute contract)
const ERROR_NOTHING_TO_UNBOND = 201 // unbond requested but no eligible stake
const ERROR_UNBOND_IN_PROGRESS = 202 // a prior unbond is still cooling down
const ERROR_COOLDOWN_NOT_ELAPSED = 203 // withdraw before the unbonding cooldown finished
const ERROR_NO_UNBONDING = 204 // withdraw with nothing in the unbonding bucket
const ERROR_KEEPER_TOO_EARLY = 205 // keeper withdraw before the owner-grace window
const ERROR_SLASH_EXCEEDS_STAKE = 206 // slash amount larger than slashable stake
const ERROR_INVALID_SPLIT = 207 // slash split bps do not sum to 10000

// Escrow
const ERROR_ESCROW_NOT_FUNDED = 220 // escrow opened without the requester's max-bid B
const ERROR_NOT_REQUESTER = 221 // settle/refund by someone other than the requester
const ERROR_NOT_ARBITER = 222 // settle by someone other than the bound arbiter
const ERROR_HASH_MISMATCH = 223 // provided result hash != the committed quorum hash
const ERROR_ALREADY_SETTLED = 224 // escrow already released
const ERROR_TIMEOUT_NOT_REACHED = 225 // refund-on-timeout before the deadline
const ERROR_PAYOUT_EXCEEDS_ESCROW = 226 // requested payout exceeds the locked escrow B

// Record anchor / dispute
const ERROR_BAD_PREV_ROOT = 240 // submitted root does not chain to the stored prev_root
const ERROR_EPOCH_REGRESSION = 241 // epoch did not advance monotonically
const ERROR_INSUFFICIENT_ANCHOR_STAKE = 242 // keeper stake-weight below the acceptance threshold
const ERROR_BAD_INCLUSION_PROOF = 243 // Merkle inclusion proof does not reproduce the root
const ERROR_DISPUTE_BOND_TOO_LOW = 244 // challenger bond below the configured minimum
const ERROR_NO_SUCH_DISPUTE = 245 // verdict for an unknown dispute id
const ERROR_NOT_VERDICT_AUTHORITY = 246 // verdict from a non-authoritative source

// ---------------------------------------------------------------------------
// Opcodes — keep TEP-74 standard values verbatim for ecosystem interop.
// ---------------------------------------------------------------------------

// TEP-74 jetton standard
const OP_JETTON_TRANSFER = 0x0f8a7ea5
const OP_JETTON_TRANSFER_INTERNAL = 0x178d4519
const OP_JETTON_NOTIFICATION = 0x7362d09c
const OP_JETTON_EXCESSES = 0xd53276db
const OP_JETTON_BURN = 0x595f07bc
const OP_JETTON_BURN_NOTIFICATION = 0x7bdd97de
const OP_PROVIDE_WALLET_ADDRESS = 0x2c76b973
const OP_TAKE_WALLET_ADDRESS = 0xd1735400

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MIN_TONS_FOR_STORAGE = ton("0.05")
const BPS_DENOM = 10000 // basis-points denominator for splits/fractions

// Status bit flags for the stake-receipt wallet.
const RECEIPT_STATUS_LOCKED = 1 // bit 0: outgoing transfers locked (default)

fun assertBasechain(addr: address) {
    assert (addr.getWorkchain() == BASECHAIN) throw ERROR_WRONG_WORKCHAIN;
}

// Storage layouts, message bodies and address helpers for the per-node stake
// contract (`StakeVault`) and its non-transferable stake-receipt jetton
// (`StakeReceiptWallet`). See BLOCKCHAIN_ECONOMICS §8 (staking/slashing/unbonding)
// and §8.5 (transfer-locked TEP-74 stake-receipt jetton).

import "common"

// ---------------------------------------------------------------------------
// Custom opcodes (distinct 32-bit tags)
// ---------------------------------------------------------------------------

const OP_TOP_UP = 0x534b_4b00
const OP_STAKE_DEPOSIT = 0x534b_4b01
const OP_STAKE_UNBOND = 0x534b_4b02
const OP_STAKE_WITHDRAW = 0x534b_4b03
const OP_STAKE_KEEPER = 0x534b_4b04
const OP_STAKE_SLASH = 0x534b_4b05
const OP_RECEIPT_BURN = 0x534b_4b06
const OP_RECEIPT_MINT = 0x534b_4b07

// ---------------------------------------------------------------------------
// Stake-receipt jetton wallet (per-holder, TEP-74 shaped, transfer-LOCKED)
// ---------------------------------------------------------------------------

struct ReceiptWalletStorage {
    status: uint4   // bit 0 = transfers locked (always set: the receipt is non-transferable)
    balance: coins  // receipt units held (1:1 with bonded TON)
    owner: address  // node operator
    master: address // the StakeVault that minted this receipt
}

fun ReceiptWalletStorage.load(): ReceiptWalletStorage {
    return ReceiptWalletStorage.fromCell(contract.getData());
}

fun ReceiptWalletStorage.save(self) {
    contract.setData(self.toCell());
}

// Mint — master-only. The receipt is non-transferable, so it is never minted via
// a sibling internal-transfer; the master credits the wallet directly. (We keep
// the standard TEP-74 transfer opcode below purely so a real transfer attempt
// hits the lock.)
struct (0x534b_4b07) ReceiptMint {
    queryId: uint64
    amount: coins
}

// TEP-74 outgoing transfer — always rejected for the stake receipt (anti-exit).
struct (0x0f8a7ea5) JettonTransfer {
    queryId: uint64
    amount: coins
    destination: address
    responseDestination: address?
    customPayload: cell?
    forwardTonAmount: coins
    forwardPayload: RemainingBitsAndRefs
}

// Master-driven burn (on withdraw or slash). Only the StakeVault may send it.
struct (0x534b_4b06) ReceiptBurn {
    queryId: uint64
    amount: coins
}

struct (0x534b_4b00) ReceiptTopUp {
    queryId: uint64
}

// Getter shape for `get_wallet_data` (TEP-74).
struct ReceiptWalletData {
    balance: coins
    owner: address
    minter: address
    code: cell
}

// ---------------------------------------------------------------------------
// Stake vault (per node) — also the receipt jetton master
// ---------------------------------------------------------------------------

// Slash split + payout targets, kept in a child cell (bit budget).
struct SlashConfig {
    treasury: address
    redundancyPool: address
    splitChallengerBps: uint16
    splitRedundancyBps: uint16
    splitBurnBps: uint16
    splitTreasuryBps: uint16
}

struct VaultConfig {
    minStake: coins         // eligibility threshold (0 = free tier, public only)
    unbondingPeriod: uint32 // cooldown secs; MUST be >= challengeWindow (validated off-chain)
    challengeWindow: uint32 // optimistic-settlement window secs
    keeperGrace: uint32     // extra secs after cooldown before a keeper may act
    keeperBountyBps: uint16 // keeper reward (bps of the withdrawn amount)
    slasher: address        // authorized slasher (the dispute contract)
    receiptWalletCode: cell // code of StakeReceiptWallet (for deterministic mint)
    slash: Cell<SlashConfig>
}

struct VaultStorage {
    owner: address         // node operator wallet
    staked: coins          // currently bonded
    unbondingAmount: coins // in cooldown (still slashable)
    unbondingAt: uint32    // unix ts the cooldown started (0 = none)
    totalSupply: coins     // receipts outstanding (== staked + unbondingAmount)
    bindingHash: uint256   // wallet<->node identity binding hash (§3.2)
    config: Cell<VaultConfig>
}

fun VaultStorage.load(): VaultStorage {
    return VaultStorage.fromCell(contract.getData());
}

fun VaultStorage.save(self) {
    contract.setData(self.toCell());
}

// Vault messages
struct (0x534b_4b01) StakeDeposit {
    queryId: uint64
    amount: coins // how much of the attached value to bond + mint as receipt
}

struct (0x534b_4b02) StakeRequestUnbond {
    queryId: uint64
    amount: coins
}

struct (0x534b_4b03) StakeWithdraw {
    queryId: uint64
}

struct (0x534b_4b04) StakeKeeperWithdraw {
    queryId: uint64
}

struct (0x534b_4b05) StakeSlash {
    queryId: uint64
    amount: coins
    reason: uint8       // SlashReason discriminant (mirrors §8.3)
    challenger: address // receives the challenger bounty share
}

// Getter shapes
struct VaultState {
    staked: coins
    unbondingAmount: coins
    unbondingAt: uint32
    totalSupply: coins
    eligible: bool // staked >= minStake AND no unbonding in progress
}

// ---------------------------------------------------------------------------
// Deterministic receipt-wallet address (mirrors the TEP-74 jetton pattern)
// ---------------------------------------------------------------------------

fun calcDeployedReceiptWallet(
    owner: address,
    master: address,
    walletCode: cell,
): AutoDeployAddress {
    val empty: ReceiptWalletStorage = {
        status: RECEIPT_STATUS_LOCKED,
        balance: 0,
        owner: owner,
        master: master,
    };
    return { workchain: BASECHAIN, stateInit: { code: walletCode, data: empty.toCell() } };
}

fun calcReceiptWalletAddress(owner: address, master: address, walletCode: cell): address {
    return calcDeployedReceiptWallet(owner, master, walletCode).calculateAddress();
}
